# Independent R verification of the exact model-ready samples generated by
# RUN_PESSIMISM_CANONICAL_REPLAY.jl. No raw data extraction or Python replay.
module PessimismCanonicalRVerify
using Dates
const PROJECT_ROOT = normpath(joinpath(@__DIR__, "..", ".."))
const RSCRIPT = joinpath(@__DIR__, "VERIFY_CANONICAL_R_PORTABLE.R")
# Backward compatibility with the v1.0 archive, which incorrectly packaged the
# R source at project-root/R rather than under pessimism_R_canonical_verify_v1.
const LEGACY_RSCRIPT = joinpath(PROJECT_ROOT,"R","VERIFY_CANONICAL_R.R")
function main()
    exe = get(ENV, "FP_RSCRIPT", "")
    if isempty(exe)
        e = Sys.which("Rscript")
        exe = e === nothing ? "" : e
    end
    if isempty(exe) || !isfile(exe)
        println("Rscript.exe not found. Set ENV[\"FP_RSCRIPT\"] to your working R path.")
        return
    end
    script = if isfile(RSCRIPT)
        RSCRIPT
    elseif isfile(LEGACY_RSCRIPT)
        println("Using R script from the original ZIP layout: ", LEGACY_RSCRIPT)
        LEGACY_RSCRIPT
    else
        println("Missing R source. Checked both ", RSCRIPT, " and ", LEGACY_RSCRIPT)
        return
    end
    source_tag = get(ENV,"FP_CANONICAL_REPLAY_TAG","20261016_140555")
    run_tag = get(ENV,"FP_R_CANONICAL_VERIFY_TAG", Dates.format(now(),"yyyymmdd_HHMMSS"))
    println("INDEPENDENT R CHECK ON CANONICAL SAMPLES")
    println("R executable: ",exe)
    println("Canonical sample tag: ",source_tag)
    cmd = addenv(`$exe --vanilla $script`,
        "FP_PROJECT_ROOT" => PROJECT_ROOT,
        "FP_CANONICAL_REPLAY_TAG" => source_tag,
        "FP_R_CANONICAL_VERIFY_TAG" => run_tag)
    proc = run(ignorestatus(cmd))
    if success(proc)
        println("\nIndependent R verification PASS. Review aggregate report and tables in Dropbox.")
    else
        println("\nIndependent R verification not yet certified (exit code ",proc.exitcode,").")
        println("Inspect 04_Verified_Results/Independent_R_",run_tag)
    end
    nothing
end
end
Base.invokelatest(PessimismCanonicalRVerify.main)
